const { sessionId, chatInput } = $input.first().json.body ?? {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const message = typeof chatInput === 'string' ? chatInput.trim() : '';
if (typeof sessionId !== 'string' || !uuid.test(sessionId) || !message || [...message].length > 2000) {
  return [{ json: { status: 400, body: { output: 'Envía una sesión válida y un mensaje de 1 a 2000 caracteres.', error: { code: 'INVALID_INPUT' } } } }];
}

const orderIds = [...new Set((message.match(/\bJS-[0-9]{3}\b/gi) ?? []).map(id => id.toUpperCase()))];
if (orderIds.length === 1) {
  return [{ json: { orderId: orderIds[0] } }];
}

const output = orderIds.length === 0
  ? '¿Cuál es el número de tu pedido? Por ejemplo, JS-101.'
  : 'Encontré varios números de pedido. ¿Cuál quieres consultar?';
return [{ json: { status: 200, body: { output, evidence: [], draft: null } } }];

const { sessionId, draftId, confirmed } = $input.first().json.body ?? {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (typeof sessionId !== 'string' || typeof draftId !== 'string' || !uuid.test(sessionId) || !uuid.test(draftId)) {
  return [{ json: { status: 400, body: { output: 'Envía una sesión y un borrador válidos.', error: { code: 'INVALID_INPUT' } } } }];
}
if (confirmed !== true) {
  return [{ json: { status: 400, body: { output: 'La radicación requiere confirmación explícita.', error: { code: 'CONFIRMATION_REQUIRED' } } } }];
}
return [{ json: { status: 503, body: { output: 'La radicación aún no está conectada en esta base.', error: { code: 'PERSISTENCE_UNAVAILABLE' } } } }];

const { pedido } = $input.first().json;
if (!pedido) {
  const output = 'No encontré ese pedido. Verifica el número e inténtalo de nuevo.';
  return [{ json: { status: 200, body: { output, evidence: [], draft: null } } }];
}

const output = `El pedido ${pedido.orderId} corresponde a ${pedido.productName} y se entregó el ${pedido.deliveredOn}.`;
const evidence = [{ source: 'pedidos', recordId: pedido.orderId, data: pedido }];
return [{ json: { status: 200, body: { output, evidence, draft: null } } }];

return [{
  json: {
    status: 503,
    body: {
      output: 'No se pudo consultar la fuente de pedidos. Inténtalo de nuevo en unos minutos.',
      error: { code: 'DATA_SOURCE_UNAVAILABLE' },
    },
  },
}];
